import type { Player } from './index';

export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Mohamed El-Shenawy', position: 'GK', age: 37, club: 'Al Ahly', captain: true, bio: {"es":"El-Shenawy se forjó en las categorías inferiores del fútbol egipcio antes de encontrar su camino hacia la cima. Se unió al sistema juvenil del Al Ahly cuando era adolescente y pasó sus años de formación allí antes de partir en 2009, primero a Tala'ea El Gaish, luego a Haras El Hodoud y más tarde a Petrojet, donde pasó tres temporadas perfeccionando su oficio. Regresó al Al Ahly en 2016 y ha sido el portero titular del club durante la mayor parte de ese tiempo, acumulando más de 350 apariciones en todas las competiciones. A nivel internacional, fue el número uno de Egipto en el Mundial de Rusia 2018, la primera aparición de los Faraones en 28 años, y ha mantenido 40 porterías a cero en 75 partidos internacionales con su país al momento de escribir este artículo. Después de ganar el MOTM para Egipto contra Sudáfrica en la Afcon 2025, dijo: \"Este premio no es solo para mí. Es para los 28 jugadores del equipo. Jugamos como el corazón de un hombre para una nación\", antes de agregar que el sindicato de porteros es \"todo uno. Jugamos juntos para Egipto y representamos a 120 millones de personas\". Con 1,91 metros, es conocido por su imponente presencia aérea y sus reflejos para detener tiros, pero puede ser propenso a cometer errores. Ahora, con 37 años, afronta una batalla para ser titular en esta Copa del Mundo contra el joven Shobeir, pero su experiencia y estatura en el fútbol egipcio lo convierten en un miembro invaluable del equipo.","en":"El-Shenawy was forged in the lower tiers of Egyptian football before finding his way to the top. He joined Al Ahly's youth system as a teenager and spent his formative years there before leaving in 2009, first to Tala'ea El Gaish, then Haras El Hodoud, and later Petrojet, where he spent three seasons honing his craft. He returned to Al Ahly in 2016 and has been the club's first-choice goalkeeper for most of that time, racking up over 350 appearances in all competitions. Internationally, he was Egypt's No 1 at the 2018 World Cup in Russia, the Pharaohs' first appearance in 28 years, and has kept 40 clean sheets in 75 caps for his country at the time of writing. After winning MOTM for Egypt against South Africa at the 2025 Afcon, he said: “This award isn’t just for me. It is for the 28 players in the squad. We play as the heart of one man for one nation,” before adding that the goalkeeper union is “all one. We play for Egypt together and represent 120million people.” At 1.91 metres, he is known for his imposing aerial presence and shot-stopping reflexes, but can be error-prone. Now 37, he faces a battle to start at this World Cup against the younger Shobeir, but his experience and stature in Egyptian football make him an invaluable member of the squad."}, special: "The veteran" },
  { number: 16, name: 'El Mahdy Soliman', position: 'GK', age: 38, club: 'Zamalek', bio: {"es":"Soliman, un veterano experimentado cuya trayectoria profesional ha recorrido gran parte del fútbol de clubes egipcio, es ahora el mayor estadista del cuerpo de porteros. El jugador de 39 años comenzó su carrera profesional con Enppi en 2008 y pasó a jugar en varios otros clubes egipcios antes de unirse al Zamalek en 2025. Con una altura de 1,89 metros, Soliman es una presencia serena y experimentada en la portería, elogiado por su compostura y su habilidad para jugar con los pies, rasgos que lo han comparado con los porteros modernos.","en":"A seasoned veteran whose career path has threaded through much of Egyptian club football, Soliman is now the elder statesman of the goalkeeping corps. The 39-year-old began his professional career with Enppi in 2008 and went on to play for several other Egyptian clubs before joining Zamalek in 2025. Standing 1.89 metres tall, Soliman is a composed, experienced presence in goal, praised for his composure and his ability to play with his feet, traits that have seen him compared to modern sweeper‑keepers."} },
  { number: 23, name: 'Mostafa ‘Oufa’ Shobeir', position: 'GK', age: 26, club: 'Al Ahly', bio: {"es":"Mientras crecía, Shobeir difícilmente podría haber escapado a la gravedad del fútbol. Su padre, Ahmed Shobeir, es uno de los porteros más célebres de Egipto como hombre entre los palos en la Copa del Mundo de 1990 y en el Al Ahly durante una carrera de 13 años. Su hijo siguió esos pasos y se unió a la academia del Al Ahly antes de debutar profesionalmente en 2020. Desde entonces, se ha consolidado como una presencia confiable para su club que siempre está tranquilo bajo presión. El jugador de 26 años mantuvo nueve porterías a cero consecutivas en la Liga de Campeones de la CAF, un récord de la competición, en el camino hacia su tercer trofeo continental durante la temporada 2023-24 y la FIFA lo describió de cara al Mundial de Clubes como \"inexpugnable\".","en":"Growing up, Shobeir could hardly have escaped football's gravity. His father, Ahmed Shobeir, is one of Egypt's most celebrated goalkeepers as the man between the sticks at the 1990 World Cup and at Al Ahly over a 13-year career. His son has followed in those footsteps, joining Al Ahly's academy before making his professional debut in 2020. Since then, he has established himself as a reliable presence for his club that is always calm under pressure. The 26-year-old kept nine consecutive clean sheets in the CAF Champions League – a competition record – on the way to his third continental trophy during the 2023-24 season and Fifa described him ahead of the Club World Cup as \"impregnable\"."}, special: "From goalkeeping family" },
  { number: 26, name: 'Mohamed Alaa', position: 'GK', age: 27, club: 'El Gouna', bio: {"es":"Alaa, el más joven de los cuatro porteros de Egipto, es una intrigante selección comodín. El jugador de 26 años se ha consolidado como uno de los porteros más capaces fuera de los tres gigantes tradicionales del país en El Gouna. La temporada pasada, Alaa fue la razón principal por la que El Gouna sobrevivió al descenso, manteniendo dos porterías a cero en tres partidos de playoffs. Su inclusión en el equipo de Egipto por primera vez durante el parón internacional de marzo refleja la voluntad de Hossam Hassan de mirar más allá de los grandes clubes en busca de talentos confiables.","en":"The youngest of Egypt's four goalkeepers, Alaa is an intriguing wildcard selection. The 26-year-old has established himself as one of the more capable shot-stoppers outside the country's three traditional giants at El Gouna. Last season, Alaa was the main reason El Gouna survived relegation, keeping two clean sheets in three playoff matches. His inclusion in Egypt's squad for the first time during the March international break reflects Hossam Hassan’s willingness to look beyond the big-club establishments for reliable talent."} },
  // Defensores
  { number: 2, name: 'Yasser Ibrahim', position: 'DF', age: 32, club: 'Al Ahly', bio: {"es":"Ibrahim se hizo un nombre en Smouha, donde pasó cuatro temporadas antes de unirse al Al Ahly en 2019 y convertirse en uno de sus pilares defensivos más confiables en el club, disputando más de 230 apariciones. También tiene la habilidad de marcar algún que otro gol importante, llegando a los titulares internacionales en 2021 después de un doblete en la primera mitad contra el Al Hilal de Arabia Saudita en la Copa Mundial de Clubes y anotando el gol de la victoria de Egipto en la prórroga contra Benin en los octavos de final de la Afcon 2025 con un cabezazo circular. A sus 33 años, se encuentra entre los defensores más experimentados del equipo y su carrera internacional ha tenido un florecimiento tardío, con solo 16 partidos internacionales a su nombre en el momento de escribir este artículo.","en":"Ibrahim made a name for himself at Smouha, where he spent four seasons before joining Al Ahly in 2019 and becoming one of their most dependable defensive pillars at the club, making more than 230 appearances. He has a knack of popping up with the odd important goal too, making international headlines in 2021 after a first-half double against Saudi Arabia’s Al Hilal in the Club World Cup and scoring Egypt’s winner in extra-time against Benin in the last-16 at the 2025 Afcon with a looping header. At 33, he is among the most experienced defenders in the squad and his international career has seen a late bloom, with just 16 senior caps to his name at the time of writing."}, special: "Late bloomer" },
  { number: 3, name: 'Mohamed Hany', position: 'DF', age: 30, club: 'Al Ahly', bio: {"es":"Hany ha pasado toda su carrera en el Al Ahly, donde se ha convertido en uno de los laterales derechos más condecorados del fútbol de clubes africanos. Ascendió al primer equipo en 2014-15 y desde entonces ha disputado más de 390 partidos con el Al Ahly, ganando ocho títulos de liga, cuatro trofeos de la Liga de Campeones de la CAF y seis Supercopas de Egipto. El estilo de juego de Hany se define por su ritmo y resistencia que le permiten operar como una amenaza de ataque por el flanco derecho. Tiene 40 partidos internacionales con la selección nacional en el momento de escribir este artículo y ha sido un participante habitual en las memorables campañas continentales del Al Ahly.","en":"Hany has spent his entire career at Al Ahly where he has become one of the most decorated right-backs in African club football. He was promoted to the first team in 2014-15 and has since made more than 390 senior appearances for Al Ahly, winning eight league titles, four CAF Champions League trophies, and six Egyptian Super Cups. Hany’s play style is defined by his pace and stamina that allows him to operate as an attacking threat down the right flank. He has 40 international caps for the national team at the time of writing and has been a regular participant in Al Ahly's memorable continental campaigns."}, special: "One-club man" },
  { number: 4, name: 'Hossam Abdelmaguid', position: 'DF', age: 27, club: 'Zamalek', bio: {"es":"Abdelmaguid, uno de los defensores jóvenes mejor valorados del fútbol egipcio, se unió al sistema del Zamalek cuando era adolescente y se ha convertido en uno de los jugadores más importantes del club. Ganó su primer título de liga en 2020-21 y añadió un segundo la temporada siguiente, luego protagonizó que el club ganara la Copa Confederación CAF y la Supercopa CAF en 2024. Abdelmaguid, de 1,94 m, es una presencia aérea dominante que puede jugar desde atrás. Sobre la competencia dentro del equipo, dijo: \"Siempre trabajo y hago lo que tengo que hacer. Quién jugará y quién no, depende del entrenador. Lo que tengo que hacer es matarme en el campo y lo que el entrenador quiera que haga, ya está. Está hecho\". Con sólo 24 años, se le considera uno de los mejores prospectos defensivos de Egipto para la próxima década. Su contrato con el Zamalek finaliza en verano y según su agente y hermano, Abdelmaguid ha tenido interés del West Brom y Anderlecht, entre otros clubes europeos.","en":"One of the most highly-rated young defenders in Egyptian football, Abdelmaguid joined Zamalek's system as a teenager and has become one of the club's most important players. He won his first league title in 2020-21 and added a second the following season, then starred as the club won the CAF Confederation Cup and the CAF Super Cup in 2024. Abdelmaguid – at 1.94m – is a dominant aerial presence who can play out from the back. On competition within the team, he said: “I always work and do what I have to do. Who will play and who will not play is up to the coach. What I have to do is to kill myself on the field and whatever the coach wants me to do, that's it. It’s done.” Still only 24, he is considered one of Egypt's best defensive prospects for the next decade. His contract with Zamalek ends in the summer and according to his agent and brother, Abdelmaguid has had interest from West Brom and Anderlecht among other European clubs."}, special: "On the rise" },
  { number: 5, name: 'Ramy Rabia', position: 'DF', age: 32, club: 'Al Ain', bio: {"es":"Ramy Rabia se unió a la academia del Al Ahly e hizo su debut en el primer equipo con solo 17 años en 2010, consolidándose rápidamente como uno de los defensores jóvenes más brillantes del fútbol egipcio. Durante sus dos etapas en el Al Ahly, interrumpidas por una breve y en gran medida infructuosa etapa en el Sporting, ganó 10 títulos de la Premier League egipcia, seis trofeos de la Liga de Campeones de la CAF y cuatro Supercopas de la CAF. Rabia, un internacional experimentado con más de 40 partidos internacionales con Egipto, ha tenido una participación fluctuante con la selección nacional a lo largo de los años, pero 2025 marcó su año más activo para su país, jugando la mayor cantidad de partidos en un solo año calendario bajo el mando del entrenador de la selección nacional, Hossam Hassan. El hombre de 32 años es un líder vocal con fuerza física y compostura en momentos de alta presión.","en":"Ramy Rabia joined Al Ahly's academy and made his first-team debut at just 17 back in 2010, quickly establishing himself as one of the brightest young defenders in Egyptian football. During his two stints at Al Ahly – interrupted by a short and largely unsuccessful spell at Sporting in between – he won 10 Egyptian Premier League titles, six CAF Champions League trophies, and four CAF Super Cups. Rabia, a seasoned international with more than 40 caps for Egypt, has seen fluctuating involvement with the national team over the years but 2025 marked his most active year for his country, playing the most matches in a single calendar year under the national team coach, Hossam Hassan. The 32-year-old is a vocal leader with physical strength and composure in high-pressure moments."}, special: "Vocal leader" },
  { number: 6, name: 'Mohamed Abdelmonem', position: 'DF', age: 27, club: 'Nice', bio: {"es":"Abdelmonem es uno de los defensores jóvenes más prometedores de Egipto, pero no siempre estuvo destinado a jugar como central. “Empecé como atacante”, dijo. \"Cuando tenía 10 años, mi club estaba en un torneo, enfrentándose a un equipo con un número 9 realmente fuerte. Estaba destrozando absolutamente a nuestros defensores, golpeándolos y empujándolos. Mi entrenador me dijo que regresara y jugara hombre a hombre contra él... Jugué un muy buen partido contra él y desde entonces, el entrenador me vio como un defensor. Llamaba a mi papá, llorando, diciéndole que quería jugar como el número 10... Ahora, trato de ser el mejor defensor que puedo ser, al mismo tiempo que marcar goles”. Abdelmonem se unió al Niza de la Ligue 1 procedente del Al Ahly en 2024, convirtiéndose en el primer jugador egipcio en representar al club del sur de Francia. El jugador de 27 años pasó sus años de formación en Al Ahly, disputando 115 partidos en tres temporadas y ganando 10 grandes honores. Obtuvo un mayor reconocimiento fuera del continente después de actuaciones estelares durante la carrera de Egipto hacia la final de la Afcon 2021. Sin embargo, ocho meses después de su carrera en Niza, se rompió el ligamento anterior cruzado y acaba de comenzar a entrenar con el primer equipo.","en":"Abdelmonem is one of Egypt’s most promising young defenders but he wasn’t always destined to play as centre-back. “I started off as an attacker,” he said. “When I was 10 years old, my club was at a tournament, facing a team with a really strong No 9. He was absolutely destroying our defenders, hitting and pushing them. My coach told me to go back and play man-to-man against him … I played a really good game against him and from then on, the coach saw me as a defender. I would call my dad, crying, telling him that I wanted to play as a No 10 … Now, I try to be the best defender I can be, while also scoring goals.” Abdelmonem joined the Ligue 1 side Nice from Al Ahly in 2024, becoming the first Egyptian player to represent the southern French club. The 27-year-old spent his formative years at Al Ahly, clocking 115 appearances across three seasons and winning 10 major honours. He gained further recognition outside of the continent after stellar performances during Egypt’s run to the final at the 2021 Afcon. However, eight months into his Nice career, he ruptured his ACL and has only just made his way into first-team training."} },
  { number: 13, name: 'Ahmed Fatouh', position: 'DF', age: 27, club: 'Zamalek', bio: {"es":"Producto de la academia juvenil de Zamalek, Fatouh fue una parte vital del equipo que ganó títulos de liga consecutivos en 2021 y 2022. Su habilidad para cruzar y su habilidad técnica lo han convertido en el favorito de los sucesivos entrenadores de las selecciones nacionales de Zamalek y Egipto, pero en agosto de 2024 recibió una sentencia de prisión suspendida de un año, una multa de 20.000 EGP (£ 275) y una licencia revocada después de que un accidente automovilístico fatal matara a un Policía de 55 años. Los exámenes confirmaron que conducía bajo los efectos de drogas. También acordó pagar a la familia de la víctima 12 millones de EGP en concepto de restitución. Refiriéndose a los rumores de que Zamalek había cubierto el pago, Fatouh dijo: \"Yo mismo pagué todo el oro. Fue mi error\". El caso dejó su carrera en el limbo durante meses y está intentando reconstruir su reputación y su forma.","en":"A product of Zamalek's youth academy, Fatouh was a vital part of the side that won back-to-back league titles in 2021 and 2022. His crossing ability and technical skill have made him a favorite of successive Zamalek and Egypt national team coaches but in August 2024 he received a one-year suspended prison sentence, a 20,000 EGP fine (£275) and a revoked license after a fatal car accident killed a 55-year-old police officer. Examination confirmed he was driving under the influence of drugs. He also agreed to pay the victim's family 12m EGP for restitution. Addressing rumours that Zamalek had covered the payment, Fatouh said: \"I paid the entire weregild myself. It was my mistake.” The case left his career in limbo for months and he is attempting to rebuild his reputation and form."} },
  { number: 15, name: 'Karim Hafez', position: 'DF', age: 29, club: 'Pyramids FC', bio: {"es":"Hafez salió joven de Egipto, pasó por Bélgica, Chipre, Francia y Turquía, y a menudo se le relacionó con movimientos de regreso a casa. Hace varios años, cuando se le preguntó sobre Al Ahly y Zamalek, dijo que no “tenía intención de regresar a Egipto”, pero el fútbol, ​​como siempre, tenía otros planes. Se mudó a casa en 2022, se unió a Pyramids y se convirtió en una opción de izquierda enormemente consistente y experimentada. Su carrera internacional ha sido intermitente. Hafez pasó cuatro años fuera del equipo antes de regresar en el amistoso de mayo sobre Rusia. No es el lateral izquierdo más rápido del equipo, pero le da a Egipto equilibrio, un pie izquierdo natural y cobertura en una posición en la que Hossam Hassan tiene pocas soluciones perfectas. Puede ser profundo en las redes sociales, y una vez escribió: \"Necesitamos aceptar que no siempre tomaremos las decisiones correctas y que a veces cometeremos errores reales, entendiendo que el fracaso no es lo opuesto al éxito. Es parte del éxito\".","en":"Hafez left Egypt young, making his way through Belgium, Cyprus, France and Turkey, and was often linked with moves back home. Several years ago, when asked about Al Ahly and Zamalek, he said that he didn't “intend to return to Egypt” – but football, as usual, had other plans. He made the move home in 2022, joined Pyramids, and grew into a hugely consistent, experienced option on the left. His international career has been intermittent. Hafez spent four years outside the squad before returning in May’s friendly win over Russia. He’s not the quickest left-back in the squad, but he gives Egypt balance, a natural left foot, and cover in a position where Hossam Hassan has few perfect solutions. He can be profound on social media, once writing: “We need to accept that we won’t always make the right decisions that we’ll screw up royally sometimes – understanding that failure is not the opposite of success. It’s part of success.”"} },
  { number: 24, name: 'Tarek Alaa', position: 'DF', age: 24, club: 'Pyramids FC', bio: {"es":"Alaa, uno de los miembros más jóvenes del equipo, es un jugador versátil que puede actuar como lateral derecho o en el papel de mediocampo defensivo con la misma compostura. Actualmente juega en el Zed FC, cedido por el Pyramids, y ha dejado su huella como un jugador técnicamente seguro y cómodo con el balón en espacios reducidos. Los informes han sugerido que Al Ahly está interesado en fichar a Alaa como suplente y eventual reemplazo de Mohamed Hany. Con sólo una internacionalidad a su nombre en el momento de escribir este artículo, Alaa todavía se está desarrollando, y la Copa del Mundo representa una oportunidad para que uno de los perfiles más jóvenes y prometedores del fútbol egipcio se pruebe en el escenario más importante.","en":"One of the youngest members of the squad, Alaa is a versatile player who can operate at right-back or in the defensive midfield role with equal composure. Currently playing for Zed FC, on loan from Pyramids, he has made his mark as a technically confident player comfortable on the ball in tight spaces. Reports have suggested Al Ahly are keen to sign Alaa as an understudy and eventual replacement for Mohamed Hany. With just one international cap to his name at the time of writing, Alaa is still developing, and the World Cup represents an opportunity for one of Egyptian football's promising younger profiles to prove himself on the biggest stage."} },
  // Volantes
  { number: 8, name: 'Emam Ashour', position: 'MF', age: 28, club: 'Al Ahly', bio: {"es":"Ashour proviene de una familia de fútbol y cuando era niño entrenaba con los grupos de mayor edad en Ghazl El Mahalla y casi abandonó el juego cuando los entrenadores juveniles lo ignoraron: “Jugué en El Mahalla solo porque mis hermanos jugaban allí”, dice. Ashour finalmente consiguió el ascenso al primer equipo de El Mahalla y pronto se convirtió en uno de los talentos más llamativos de Egipto. En 2019, fichó por el Zamalek, donde ayudó a los Caballeros Blancos a ganar títulos nacionales y se abrió camino en la selección nacional, e incluso se mudó brevemente a Midtjylland en Dinamarca, antes de unirse a los acérrimos rivales de su antiguo equipo, el Al Ahly, en 2023. Allí, el estilo y la puntuación de Ashour realmente lo llevaron a las altas esferas del fútbol nacional y el mediocampista se convirtió en el máximo goleador de la liga en 2024-25. Sin embargo, las lesiones han sido recurrentes después de que una fractura de clavícula interrumpiera su Copa Mundial de Clubes en 2025. Ashour se despliega como el número 10 en ataque de Egipto, deambulando entre líneas, creando oportunidades y, por lo general, acompañando a otros creadores de juego en un papel libre.","en":"Ashour hails from a football family and as a child, he trained with the older age groups at Ghazl El Mahalla and nearly quit the game when youth coaches overlooked him: “I played at El Mahalla only because my brothers played there,” he says. Ashour eventually earned promotion to El Mahalla’s first team and soon became one of Egypt’s most eye-catching talents. In 2019, he signed for Zamalek, where he helped the White Knights win domestic titles and forced his way into the national team, later even moving briefly to Midtjylland in Denmark, before joining his former team’s bitter rivals Al Ahly in 2023. There, Ashour’s flair and scoring really took him to the upper echelons of domestic football and the midfielder became the league’s top scorer in 2024-25. Injuries, however, have been recurring after a broken collarbone cut short his Club World Cup in 2025. Ashour is deployed as an attacking No 10 for Egypt, roaming between the lines, creating chances, and typically partnering other playmakers in a free role."} },
  { number: 11, name: 'Mostafa Ziko', position: 'MF', age: 26, club: 'Pyramids FC', bio: {"es":"Mostafa Mohamed Zaki Abdelraouf, también conocido como Ziko, ha recorrido un largo camino hasta llegar a la selección nacional. Desde Shibin El-Kom se abrió camino a través de Haras El Hodoud, ZED y Pyramids para ocupar su lugar entre la élite de Egipto. Su orgullosa madre dice que su ascenso se produjo después de “años de esfuerzo y desafíos”, y agrega que tuvo que asumir la responsabilidad demasiado temprano en la vida cuando su padre murió cuando Ziko tenía solo 11 años. Su debut en Egipto difícilmente podría haber sido mejor. En el amistoso de preparación contra Rusia en El Cairo entró y marcó el único gol del partido con un cabezazo en la segunda parte. Después dijo que “incluso si yo mismo hubiera escrito el guión, no podría haber imaginado que mi debut fuera de esta manera”. No se espera que Ziko sea titular este verano: las posiciones delanteras de Egipto están abarrotadas, con Mohamed Salah, Omar Marmoush, Trezeguet, Ibrahim Adel y otros por delante de él. Pero su valor puede ser como un jugador de banco que puede cubrir varios roles de ataque y llegar sin la carga de expectativas que cargan los nombres más importantes.","en":"Mostafa Mohamed Zaki Abdelraouf – AKA Ziko – has taken the long road into the national team. From Shibin El-Kom he worked his way through Haras El Hodoud, ZED and Pyramids to take his place among Egypt’s elite. His proud mother says his rise came after “years of effort and challenges”, adding that he had to take responsibility too early in life when his father died when Ziko was just 11. His Egypt debut could hardly have gone better. In the warm-up friendly against Russia in Cairo he came on and scored the only goal of the match with a second-half header. Afterwards he said that “even if I had scripted the scenario myself, I could not have imagined my debut going this way”. Ziko is not expected to be a starter this summer – Egypt’s positions up front are crowded, with Mohamed Salah, Omar Marmoush, Trezeguet, Ibrahim Adel and others ahead of him. But his value may be as a bench player who can cover several attacking roles and arrive without the burden of expectation carried by the bigger names."}, special: "Had to mature early" },
  { number: 14, name: 'Hamdy Fathy', position: 'MF', age: 31, club: 'Al-Wakrah', bio: {"es":"Un combativo centrocampista defensivo cuya carrera le ha llevado desde las trincheras del fútbol egipcio hasta la gloria continental con el Al Ahly. Fathy comenzó su carrera profesional con Damanhour, se mudó a Enppi en 2015, luego a Petrojet un año después, y se unió al Al Ahly en 2019. En Al Ahly, su carrera realmente floreció, estableciéndose rápidamente como titular habitual y logró un éxito impresionante, ganando tres partidos de la Premier League egipcia, la Copa de Egipto, la Supercopa de Egipto y la Liga de Campeones de la CAF. Luego se mudó al equipo qatarí Al-Wakrah en 2023. En el verano de 2025, Al Ahly lo trajo de regreso en préstamo específicamente para participar en el Mundial de Clubes de 2025. Fathy también es un habitual de la selección nacional, con 62 apariciones a su nombre al momento de escribir este artículo, jugando como disruptor frente a la defensa. \"Puedo jugar de 6, de central en un tres, en un dos. Lo que quiera el entrenador lo haré\", afirma. \"No tengo preferencia. Lo que me importa son sólo los mejores intereses del equipo\".","en":"A combative defensive midfielder whose career has taken him from the trenches of Egyptian football to continental glory with Al Ahly. Fathy began his professional career with Damanhour, moved to Enppi in 2015, then to Petrojet one year later, and joined Al Ahly in 2019. At Al Ahly, his career truly flourished, quickly establishing himself as a regular starter and achieved impressive success, winning three each of the Egyptian Premier League, the Egyptian Cup, the Egyptian Super Cup and the CAF Champions League. He then moved to the Qatari side Al-Wakrah in 2023. In the summer of 2025, Al Ahly brought him back on loan specifically to participate in the 2025 Club World Cup. Fathy is also a national team regular, with 62 appearances to his name at the time of writing, playing as a disruptor in front of the defence. “I can play as a No 6, as a centre-back in a three, in a two. Whatever the coach wants, I will do,” he says. “I have no preference. What matters to me is only the best interests of the team.”"}, special: "Anchor" },
  { number: 17, name: 'Mohanad Lasheen', position: 'MF', age: 27, club: 'Pyramids FC', bio: {"es":"Lasheen es un jugador que conoce el valor del trabajo duro. Formó parte del equipo de Alassiouty (ahora Pyramids) que consiguió el ascenso a la Premier League egipcia, anotando el gol de la victoria que garantizó su ascenso cinco semanas antes del final de la temporada. Es un mediocampista central versátil con buen ojo para el pase y una sólida ética de trabajo defensivo. Cuando Lasheen se unió al equipo de Egipto en 2025 durante las eliminatorias para la Copa del Mundo, lo hizo mientras luchaba contra una lesión. En ese momento, dijo que desde el inicio del campamento los jugadores entendieron el peso de las eliminatorias y que él estaba “corriendo contra el tiempo” para estar en forma. Con 21 partidos internacionales, sigue siendo una parte vital de la rotación del mediocampo de la selección nacional y se le consideró apto justo a tiempo para la Copa del Mundo.","en":"Lasheen is a player who knows the value of hard work. He was a part of the Alassiouty (now Pyramids) squad that won promotion to the Egyptian Premier League, scoring the winning goal that guaranteed their ascent five weeks before the end of the season. He is a versatile central midfielder with a keen eye for a pass and a strong defensive work ethic. When Lasheen joined Egypt’s squad in 2025 during the World Cup qualifiers, he did so while battling injury. At the time, he said that from the start of the camp, the players understood the weight of the qualifiers and that he was “racing against time” to be fit. With 21 caps, he remains a vital part of the national team's midfield rotation and was deemed fit just in time for the World Cup."} },
  { number: 18, name: 'Nabil \'Dunga\' Emad', position: 'MF', age: 30, club: 'Al-Najma', bio: {"es":"Nabil Emad, más conocido como Dunga, pasó por las categorías inferiores del fútbol egipcio antes de pasar al Pyramids y luego al Zamalek en 2022, donde se convirtió en un pilar del mediocampo defensivo. Allí ganó la Premier League egipcia, la Copa de Egipto, la Copa Confederación CAF y la Supercopa CAF antes, en la última ventana de invierno, uniéndose al Al-Najma de Arabia Saudita. Su apodo lo acompaña desde hace mucho tiempo, desde que uno de sus entrenadores junior lo comparó con la leyenda brasileña ganadora de la Copa del Mundo. Para la selección nacional, Dunga ofrece a Hossam Hassan una opción más conservadora en el centro del campo. Si bien puede que no sea tan llamativo como Emam Ashour ni tan expansivo como Marwan Attia, sin duda será útil cuando Egipto necesite ganar duelos y segundos balones. Su lugar este verano quedó en duda días después de que se anunciara la plantilla cuando fue objeto de acusaciones de violación por parte de una mujer italiana. Su abogado, Shaaban Saeed, negó rotundamente las acusaciones y afirmó que su cliente fue víctima de \"una campaña para distorsionar la imagen del jugador\".","en":"Nabil Emad, better known as Dunga, came through the lower ranks of Egyptian football before moving to Pyramids, then Zamalek in 2022, where he became a defensive midfield mainstay. He won the Egyptian Premier League, the Egyptian Cup, CAF Confederation Cup and CAF Super Cup there before, in the last winter window, joining Saudi Arabia’s Al-Najma. His nickname has been with him a long time, ever since one of his junior coaches compared him to the Brazilian World-Cup-winning legend. For the national team, Dunga provides Hossam Hassan with a more conservative midfield option. While he may not be as flashy as Emam Ashour or as expansive as Marwan Attia, he will certainly be useful when Egypt need to win duels and second balls. His place this summer was thrown into doubt days after the squad was announced when he was the subject of allegations of rape made by an Italian woman. His lawyer, Shaaban Saeed, strongly denied the claims, saying his client was victim of \"a campaign to distort the player's image\"."} },
  { number: 19, name: 'Marwan Attia', position: 'MF', age: 28, club: 'Al Ahly', bio: {"es":"Attia es un mediocampista central trabajador conocido por su motor y sus pases. Ascendió de rango en Al Ittihad Alexandria, ingresando a su primer equipo en 2019. Pasó cuatro temporadas como presencia constante e incluso capitán antes de mudarse al Al Ahly. “He jugado al fútbol desde que tenía siete años y mi sueño de siempre […] era usar esa camiseta roja”, dijo Attia. \"Cuando supe que el Al Ahly me quería no lo pensé dos veces. Sentí en mis huesos que estaría viviendo el sueño de mi infancia\". Ha surgido bajo Hossam Hassan como el contraste para equipos más ofensivos, aunque en ocasiones también puede avanzar. En la Afcon 2025, irrumpió en el área para anotar un brillante primer gol contra Benin y luego anotó un centro para el gol de la victoria. Fuera del campo, Attia ha demostrado una determinación silenciosa en tiempos difíciles, perdió a su padre en 2023, pero regresó inmediatamente a la acción para desempeñar un papel clave en asegurar un triplete para Al Ahly.","en":"Attia is a hard-working central midfielder known for his engine and passing. He came up through the ranks at Al Ittihad Alexandria, breaking into their first team in 2019. He spent four seasons as a steady presence and even captain before moving to Al Ahly. “I have been playing football since I was seven, and my forever dream […] was to wear that red jersey,” Attia said. “When I knew Al Ahly wanted me, I didn’t think twice. I felt in my bones that I would be living my childhood dream”. He has emerged under Hossam Hassan as the foil to more attack-minded teams though he can also surge forward on occasion. At the 2025 Afcon, he burst into the box to score a brilliant opener against Benin, and later whipped in a cross for the winner. Off the field, Attia has shown quiet determination in tough times, losing his father in 2023, yet immediately returning to action to play a key role in securing a treble for Al Ahly."}, special: "Midfield lynchpin" },
  { number: 21, name: 'Mahmoud Saber', position: 'MF', age: 24, club: 'Pyramids FC', bio: {"es":"Sabre, ahora con el ZED, ha tomado un camino sinuoso a través del fútbol egipcio: del Nogoom FC al Pyramids, luego cedido y breves periodos en el ZED y el Smouha antes de regresar al ZED nuevamente en 2025. A sus 24 años, ya ha jugado 14 veces con la selección absoluta a pesar de debutar en 2024. Sabre es conocido por su capacidad para encontrar espacios en mediocampos abarrotados y sus precisos pases en profundidad. Es diestro, tácticamente adaptable y puede jugar como mediocampista ofensivo o por la izquierda cuando sea necesario.","en":"Saber, now with ZED, has taken a winding route through Egyptian football: from Nogoom FC to Pyramids, then loans and short spells with ZED and Smouha before returning to ZED again in 2025. At 24, he has already played for the senior national team 14 times despite only making his debut in 2024. Saber is known for his ability to find space in crowded midfields and his precise through-balls. He is right-footed, tactically adaptable, and can play as an attacking midfielder or off the left when required."} },
  // Delanteros
  { number: 7, name: 'Mahmoud Hassan ‘Trezeguet’', position: 'FW', age: 32, club: 'Al Ahly', bio: {"es":"El apodo de Trezeguet, tomado de la leyenda del fútbol francés David Trezeguet, lo ha acompañado desde su adolescencia y ha definido una carrera tan colorida como la de cualquier futbolista egipcio. Ingresó al primer equipo del Al Ahly a los 18 años, ayudándolos a ganar títulos consecutivos de la Liga de Campeones de la CAF en 2012 y 2013. Tuvo su mayor impacto europeo en Kasimpasa en Turquía, convirtiéndose en el séptimo egipcio en alcanzar cifras dobles en una liga europea y estableciendo un nuevo récord de goles de un egipcio en la máxima categoría turca. Aston Villa lo fichó en 2019, donde sus goles les ayudaron a evitar la caída en 2020. Posteriormente regresó a Turquía antes de regresar al Al Ahly. Tiene más de 90 partidos internacionales y más de 20 goles con Egipto y sus contribuciones a la campaña de clasificación para la Copa Mundial 2018 establecieron su legado en la historia del fútbol egipcio. \"He jugado en la mejor liga del mundo, la Premier League. He jugado frente a un público increíble en Turquía. Lo dejaría todo si fuera necesario\", dijo Trezeguet. \"Nunca dejaría de representar a Egipto\". Ahora, a sus 31 años, llega a este Mundial como uno de los jugadores más experimentados de la plantilla y como un jugador al que muchos de sus compañeros crecieron viendo.","en":"Trezeguet's nickname, borrowed from the French football legend David Trezeguet, has been with him since his teenage years and has defined a career as colourful as any Egyptian footballer's. He broke into Al Ahly's first team at 18, helping them win back-to-back CAF Champions League titles in 2012 and 2013. He made his biggest European impact at Kasimpasa in Turkey, becoming the seventh Egyptian to reach double figures in a European league and setting a new record for goals by an Egyptian in the Turkish top-flight. Aston Villa signed him in 2019 where his goals helped them avoid the drop in 2020. He later returned to Turkey before moving back to Al Ahly. He has over 90 caps and more than 20 goals for Egypt and his contributions to the 2018 World Cup qualifying campaign established his legacy in Egyptian football history. “I’ve played in the best league in the world, the Premier League. I’ve played in front of incredible crowds in Turkey. I would give those all up if I needed to,” Trezeguet said. “I would never give up representing Egypt.” Now, at 31, he arrives at this World Cup as one of the squad's most experienced players and as a player whom many of his teammates grew up watching."} },
  { number: 9, name: 'Hamza Abdelkarim', position: 'FW', age: 18, club: 'Al Ahly', bio: {"es":"El jugador más joven de este grupo con diferencia y una de las perspectivas más interesantes del fútbol egipcio. Pasó por la academia del Al Ahly, jugó para Egipto en la categoría Sub-17 y luego se unió al Barcelona B durante la ventana de transferencias de invierno en calidad de préstamo, con opción a compra. Abdelkarim, el primer jugador egipcio en la historia del club catalán, ya ha empezado a hacerse un nombre en la selección sub-19A, marcando cinco goles en siete partidos ligueros. Su convocatoria a Egipto este verano es claramente una apuesta, pero no descabellada. Hossam Hassan ha dejado fuera a los delanteros más consagrados y ha mantenido a un delantero adolescente que apenas ha comenzado su carrera senior, pero el atractivo es obvio: Hamza, conocido como “El Haaland egipcio”, es alto, móvil y un jugador natural del área de penalti en un equipo que, por lo demás, se apoya en gran medida en delanteros abiertos y corredores del mediocampo para marcar goles. Es poco probable que le pidan que lidere el ataque de Egipto, pero si el equipo necesita un cuerpo tardío en el área, el jugador más joven del equipo de repente puede volverse extremadamente importante.","en":"The youngest player in this group by some distance, and one of the most exciting prospects in Egyptian football. He came through Al Ahly’s academy, played for Egypt at Under-17 level, and then joined Barcelona B during the winter transfer window on loan, with an option to buy. Abdelkarim, the first Egyptian player in the Catalan club’s history, has already started to make a name for himself with their Under-19A side, scoring five goals in seven league matches. His senior Egypt call-up this summer is clearly a gamble, but not a wild one. Hossam Hassan has left out more established forwards and kept a teenage striker who has barely started his senior career, but the attraction is obvious: Hamza, known as “The Egyptian Haaland”, is tall, mobile, and a natural penalty-box player in a squad that otherwise leans heavily on wide forwards and midfield runners for goals. He is unlikely to be asked to carry Egypt’s attack, but if the side needs a late body in the box, the youngest player in the squad may suddenly become extremely important."}, special: "'The Egyptian Haaland'" },
  { number: 10, name: 'Mohamed Salah', position: 'FW', age: 34, club: 'Liverpool', bio: {"es":"El rey egipcio necesita poca presentación y su carrera se ha convertido en un argumento permanente contra los límites máximos. En diciembre, se convirtió en el jugador con más participaciones en goles en un solo club en la historia de la Premier League, con 277, superando a Wayne Rooney. Nadie ha ganado más premios Bota de Oro en la historia de la liga que sus cuatro (junto con Thierry Henry), y es el jugador extranjero con mayor puntuación en la liga. Salah ha llevado a Egipto a dos finales de la Copa Africana de Naciones en 2017 y 2021, y fue incluido en el equipo del torneo en cada carrera. Sin embargo, su momento decisivo en la selección nacional sigue siendo el penalti en tiempo de descuento contra el Congo en octubre de 2017 que envió a Egipto a la Copa del Mundo de 2018 y puso fin a una ausencia de 28 años de la competición. Desde que anunció que pondría fin a su histórica etapa de nueve años en el Liverpool, ha jugado con cierta libertad, a pesar de no estar en su mejor momento esta temporada. Salah ha marcado 65 goles internacionales al momento de escribir este artículo, ocupando el segundo lugar en la lista de todos los tiempos de su país y persiguiendo el récord de Hossam Hassan, el entrenador en jefe de Egipto. Como capitán y punto focal del equipo, sigue siendo el jugador en torno al cual los sucesivos entrenadores han construido sus planes.","en":"The Egyptian King needs little introduction, and his career has become a permanent argument against ceilings. In December, he became the player with the most goal involvements at a single club in Premier League history, with 277, surpassing Wayne Rooney. No one has won more Golden Boot awards in the league’s history than his four (joint-top with Thierry Henry), and he is the highest scoring foreign player in the league. Salah has led Egypt to two Africa Cup of Nations finals in 2017 and 2021, and he was named in the team of the tournament on each run. His defining national team moment, however, remains the stoppage time penalty against Congo in October 2017 that sent Egypt to the 2018 World Cup and ended a 28-year absence from the competition. Since announcing that he will call time on his storied nine-year spell at Liverpool, he has played with a certain freedom, despite not being at his best this season. Salah has scored 65 international goals at the time of writing, second on his country’s all-time list and chasing the record held by Hossam Hassan, Egypt's head coach. As captain and the focal point of the squad, he remains the player around whom successive coaches have built their plans."}, special: "National hero" },
  { number: 12, name: 'Haissem Hassan', position: 'FW', age: 23, club: 'Real Oviedo', bio: {"es":"La historia de la elegibilidad internacional de Haissem Hassan es una historia de múltiples reclamos en competencia. Nacido en París, de padre egipcio y madre tunecina, y habiendo representado a Francia en las categorías inferiores, fue buscado por dos federaciones nacionales. Túnez confirmó que se habían acercado a él; Egipto también se puso en contacto. Hassan tomó su decisión el 15 de marzo de 2026 de representar a Egipto, expresando su deseo de competir en la Copa del Mundo. Inició su carrera profesional con Châteauroux en Francia con solo 16 años en 2018, luego se mudó a Villarreal en 2020, pasando un tiempo en sus filas de reserva antes de cesiones en Mirandés y Sporting Gijón. En agosto de 2024, fichó por el Real Oviedo de la segunda división española, antes de ascender a La Liga, y desde entonces se ha convertido en titular habitual. El jugador de 24 años es predominantemente un atacante por la derecha, rápido, directo y cómodo en situaciones de 1 contra 1.","en":"Haissem Hassan's international eligibility story is a tale of multiple competing claims. Born in Paris to an Egyptian father and Tunisian mother, and having represented France at youth level, he was sought by two national federations. Tunisia confirmed they had approached him; Egypt also made contact. Hassan made his decision on 15 March 2026 to represent Egypt, expressing his desire to compete at the World Cup. He launched his professional career with Châteauroux in France at just 16 in 2018, then moved to Villarreal in 2020, spending time in their reserve ranks before loan spells at Mirandés and Sporting Gijón. In August 2024, he joined Real Oviedo in Spain's second division, before being promoted to La Liga, and has become a regular starter since. The 24-year-old is predominantly a right-sided attacker, quick, direct, and comfortable in 1v1 situations."}, special: "Newcomer" },
  { number: 20, name: 'Ibrahim Adel', position: 'FW', age: 25, club: 'FC Nordsjælland', bio: {"es":"Adel, un veloz extremo izquierdo, surgió de la escena de Port Said, descubierto a la edad de ocho años. Hijo del exdelantero del Zamalek Ashraf Adel, heredó el amor por el juego de su familia. Su velocidad explosiva y su ojo para el gol llamaron la atención rápidamente y se ganó un traslado a Pyramids en 2018, ayudándolos a ganar sus dos primeros trofeos, la Liga de Campeones Africana y la Copa de Egipto, con su arrogancia y sus golpes de largo alcance le valieron el apodo de \"Baby Hulk\". El Getafe intentó ficharle, incluso llevándole en avión a España, pero Pirámides se mantuvo firme. Adel dijo más tarde: \"El club quiere retenerme... y respeto su decisión\". Ahora está cedido en el club danés FC Nordsjælland, donde su ejecutivo deportivo egipcio, Hossam El Zanati, dijo que el club lo había seguido durante más de tres años y necesitaba una “superestrella” para abrirse camino desde Egipto. Fue nombrado mejor jugador de la Copa Africana de Naciones Sub-23 de 2023 y tiene 21 partidos internacionales absolutos con tres goles.","en":"A lightning-fast left winger, Adel emerged from the Port Said scene, scouted at the age of eight. The son of the former Zamalek forward Ashraf Adel, he inherited his family's love of the game. His explosive speed and eye for goal drew attention quickly and he earned a move to Pyramids in 2018, helping them win their first two trophies ever, the African Champions League and the Egyptian Cup with his swagger and long-range strikes earning him the nickname “Baby Hulk”. Getafe tried to sign him, even flying him to Spain, but Pyramids held firm. Adel later said: “The club wants to keep me… and I respect their decision.” Now on loan at the Danish club FC Nordsjælland, where their Egyptian sporting executive, Hossam El Zanati, said the club had followed him for over three years and needed a “superstar” to open a pathway from Egypt. He was named best player at the 2023 Under-23 Africa Cup of Nations and has 21 senior international caps with three goals."}, special: "Speed bullet" },
  { number: 22, name: 'Omar Marmoush', position: 'FW', age: 26, club: 'Manchester City', bio: {"es":"En otra vida, Marmoush podría haber vestido los colores rojo y blanco de un equipo diferente. \"Después de unos tres años de estar en Alemania, Canadá se puso en contacto conmigo\", ha dicho el delantero. \"Me dijeron que sabían que tenía ciudadanía y querían que me uniera a su equipo. El entrenador me llamó personalmente. Pero [mi decisión] ya se había tomado hace mucho tiempo. Para mí, la selección egipcia está por encima de cualquier otra cosa\". A los 17 años dejó su huella en Wadi Degla; Luego se unió a Wolfsburg, Stuttgart y St. Pauli antes de que sus actuaciones en el Eintracht Frankfurt le aseguraran una transferencia al Manchester City. \"Sin él no sería posible clasificarse para la Liga de Campeones y llegar a la final de la Copa FA\", dijo el entrenador de su club, Pep Guardiola. \"Es un jugador especial. Lo veo más como un delantero que como un verdadero extremo\". Hossam Hassan aún tiene que seguir el consejo de Guardiola y, a menudo, despliega a Marmoush en el flanco. Aun así, con 46 partidos internacionales y 10 goles con la selección nacional en el momento de escribir este artículo, él y Salah son los primeros nombres en la lista del equipo.","en":"In another life, Marmoush might have donned the red-and-white colors of a different team. “After about three years of being in Germany, Canada contacted me,” the forward has said. “They told me they knew I had citizenship and wanted me to join their setup. The coach called me personally. But [my decision] had already been made a long time ago. The Egyptian national team, to me, is above anything else.” At 17, he made his mark at Wadi Degla; then joined Wolfsburg, Stuttgart and St. Pauli before his Eintracht Frankfurt performances secured a transfer to Manchester City. “Without him it would not be possible to qualify for the Champions League and reach the FA Cup final,” said his club manager, Pep Guardiola. “He’s a special player. I see him more as a striker not a proper winger.” Hossam Hassan has yet to follow Guardiola’s advice, often deploying Marmoush on the flank. Still, with 46 caps and 10 goals for the national team at the time of writing, he and Salah are the first names on the team sheet."} },
  { number: 25, name: 'Ahmed Sayed ‘Zizo’', position: 'FW', age: 29, club: 'Al Ahly', bio: {"es":"Zizo se ha ganado la reputación de ser uno de los extremos más goleadores y clínicos del fútbol egipcio. Su mejor campaña llegó en la 2021-22 con el Zamalek, cuando acabó como máximo goleador de la liga con 19 goles. Cuando su contrato expiró en junio de 2025, Al Ahly, el rival más feroz del Zamalek, actuó rápidamente para fichar a Zizo por cuatro años, convirtiéndolo en una de las transferencias más controvertidas del fútbol egipcio. “¿Cómo es posible que el Al Ahly no fiche al mejor jugador de Egipto, especialmente si es agente libre?” dijo el ex portero egipcio y del Zamalek, Nader El-Sayed. \"El acuerdo con Zizo no fue rencoroso. Es el mejor jugador de África y llegó gratis. El Al Ahly es similar al Real Madrid\". El jugador de 30 años aporta ritmo, técnica y un ojo infalible para el gol a las amplias opciones de ataque de Egipto. “Siempre quise ser futbolista”, afirma. \"Nunca pensé en el nivel que podría alcanzar, ni siquiera soñé con jugar para Egipto, pero siempre iba a ser futbolista. No había otra opción\".","en":"Zizo has carved out a reputation as one of Egyptian club football's most clinical, goalscoring wingers. His finest campaign came in 2021-22 with Zamalek, when he finished as the league’s top scorer with 19 goals. When his contract expired in June 2025, Al Ahly, Zamalek's fiercest rivals, moved swiftly to sign Zizo on a four-year deal, making it one of the most controversial transfers in Egyptian football. “How could Al Ahly not sign the best player in Egypt, especially since he was a free agent?” said the former Egyptian and Zamalek goalkeeper, Nader El-Sayed. “The Zizo deal wasn’t spiteful. He’s the best player in Africa, and he came on a free transfer. Al Ahly is similar to Real Madrid.” The 30-year-old brings pace, technique, and an unerring eye for goal to Egypt's wide attacking options. “I always wanted to be a footballer,” he says. “I never thought about what level I could reach, didn’t even dream about playing for Egypt, but I was always going to be a footballer. There was no other option.”"}, special: "Unsung hero" },
];

export const lineup = {
  formation: '4-3-3',
  startingXI: [1, 3, 6, 2, 13, 19, 8, 25, 10, 22, 7]
};
